"95\" rx=\"16\" fill=\"#ec4899\" fill-opacity=\"0.12\" stroke=\"#ec4899\" stroke-width=\"2\"/><text x=\"165\" y=\"689.5\" text-anchor=\"start\" fill=\"#ec4899\" font-size=\"24\" font-weight=\"bold\">5.</text><text x=\"210\" y=\"689.5\" text-anchor=\"start\" fill=\"#ffffff\" font-size=\"18\">Revisit all seven answers every quarter</text>\n</svg>",
