      "svg": "<svg viewBox=\"0 0 1100 1100\" class=\"lesson-visual\">\n<rect x=\"0\" y=\"0\" width=\"1100\" height=\"1100\" fill=\"#1a1a2e\"/><text x=\"550\" y=\"55\" text-anchor=\"middle\" fill=\"#ffd700\" font-size=\"30\" font-weight=\"bold\">KNOWLEDGE CHECK</text><rect x=\"100\" y=\"110\" width=\"900\" height=\"150\" rx=\"16\" fill=\"#6366f1\" fill-opacity=\"0.1\" stroke=\"#6366f1\" stroke-width=\"2\"/><text x=\"550\" y=\"150\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"17\">A government expects decline and drafts</text><text x=\"550\" y=\"180\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"17\">detailed five-year plans to manage an</text><text x=\"550\" y=\"210\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"17\">orderly decline and conserve resources</text><rect x=\"650\" y=\"320\" width=\"350\" height=\"140\" rx=\"16\" fill=\"#f59e0b\" fill-opacity=\"0.18\" stroke=\"#f59e0b\" stroke-width=\"2\"/><text x=\"825\" y=\"365\" text-anchor=\"middle\" fill=\"#f59e0b\" font-size=\"19\" font-weight=\"bold\">DEFINITE</text><text x=\"825\" y=\"395\" text-anchor=\"middle\" fill=\"#f59e0b\" font-size=\"19\" font-weight=\"bold\">PESSIMISM</text><text x=\"825\" y=\"425\" text-anchor=\"middle\" fill=\"#10b981\" font-size=\"15\" font-weight=\"bold\">CORRECT</text><rect x=\"150\" y=\"320\" width=\"400\" height=\"140\" rx=\"16\" fill=\"#888\" fill-opacity=\"0.1\" stroke=\"#888\" stroke-width=\"2\"/><text x=\"350\" y=\"365\" text-anchor=\"middle\" fill=\"#888\" font-size=\"15\">not indefinite —</text><text x=\"350\" y=\"395\" text-anchor=\"middle\" fill=\"#888\" font-size=\"15\">the plan is specific,</text><text x=\"350\" y=\"425\" text-anchor=\"middle\" fill=\"#888\" font-size=\"15\">not vague anxiety</text><text x=\"550\" y=\"550\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"16\">Worse future + a specific plan</text><text x=\"550\" y=\"580\" text-anchor=\"middle\" fill=\"#ffffff\" font-size=\"16\">= definite pessimism</text>\n</svg>",
